'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const {parseRequest,buildUpstream,handleFranceV2}=require('./worker-france-v2');
const url='https://example.com/v2/france?lat=43.3&lon=5.4&dist=10&fuel=Gazole';
const req=(u=url)=>new Request(u);
const row=(id,price=1.7)=>({id,geom:{lat:43.3,lon:5.4},gazole_prix:price});
const fetchPages=(pages,seen=[])=>async(u)=>{seen.push(new URL(u));const offset=Number(new URL(u).searchParams.get('offset'));const limit=Number(new URL(u).searchParams.get('limit'));return {ok:true,json:async()=>({total_count:pages.length,results:pages.slice(offset,offset+limit)})}};
test('validation coordonnées',()=>assert.equal(parseRequest(url).radiusKm,10));
test('refuse absence de lat',()=>assert.throws(()=>parseRequest('https://x/?lon=2&dist=5&fuel=Gazole')));
test('refuse rayon supérieur 50',()=>assert.throws(()=>parseRequest(url.replace('dist=10','dist=100'))));
test('refuse carburant inconnu',()=>assert.throws(()=>parseRequest(url.replace('Gazole','Jet'))));
test('refuse latitude hors plage',()=>assert.throws(()=>parseRequest(url.replace('43.3','100'))));
test('refuse longitude hors plage',()=>assert.throws(()=>parseRequest(url.replace('5.4','200'))));
test('URL upstream avec offset',()=>assert.equal(new URL(buildUpstream(parseRequest(url),100)).searchParams.get('offset'),'100'));
test('filtre géographique upstream',()=>assert.match(new URL(buildUpstream(parseRequest(url),0)).searchParams.get('where'),/within_distance/));
test('réponse vide complète',async()=>{const r=await handleFranceV2(req(),{fetchFn:fetchPages([])});assert.equal((await r.json()).total,0)});
test('plusieurs pages upstream',async()=>{const seen=[];const r=await handleFranceV2(req(),{fetchFn:fetchPages([row(1),row(2),row(3)],seen),pageSize:2});const j=await r.json();assert.equal(j.total,3);assert.equal(seen.length,2);assert.equal(j.complete,true)});
test('filtre prix absent',async()=>{const r=await handleFranceV2(req(),{fetchFn:fetchPages([row(1,null),row(2,1.7)])});assert.equal((await r.json()).total,1)});
test('filtre prix zéro',async()=>{const r=await handleFranceV2(req(),{fetchFn:fetchPages([row(1,0),row(2,1.7)])});assert.equal((await r.json()).total,1)});
test('upstream HTTP erreur => 503',async()=>{const r=await handleFranceV2(req(),{fetchFn:async()=>({ok:false})});assert.equal(r.status,503)});
test('total change => 503',async()=>{let i=0;const r=await handleFranceV2(req(),{pageSize:1,fetchFn:async()=>({ok:true,json:async()=>({total_count:++i===1?2:3,results:[row(i)]})})});assert.equal(r.status,503)});
test('identifiants dupliqués => 503',async()=>{const r=await handleFranceV2(req(),{fetchFn:fetchPages([row(1),row(1)])});assert.equal(r.status,503)});
test('plafond atteint => 503',async()=>{const r=await handleFranceV2(req(),{maxRecords:1,fetchFn:fetchPages([row(1),row(2)])});assert.equal(r.status,503)});
test('nombre pages insuffisant => 503',async()=>{const r=await handleFranceV2(req(),{maxPages:1,pageSize:1,fetchFn:fetchPages([row(1),row(2)])});assert.equal(r.status,503)});
test('page upstream invalide => 503',async()=>{const r=await handleFranceV2(req(),{fetchFn:async()=>({ok:true,json:async()=>({results:[]})})});assert.equal(r.status,503)});
test('annulation => 503',async()=>{const a=new AbortController();a.abort();const r=await handleFranceV2(req(),{signal:a.signal,fetchFn:fetchPages([row(1)])});assert.equal(r.status,503)});
test('réponse CORS',async()=>{const r=await handleFranceV2(req(),{fetchFn:fetchPages([])});assert.equal(r.headers.get('Access-Control-Allow-Origin'),'*')});
test('prix autre carburant',async()=>{const r=await handleFranceV2(req(url.replace('Gazole','E10')),{fetchFn:fetchPages([{id:1,e10_prix:1.6},{id:2,gazole_prix:1.7}])});assert.equal((await r.json()).total,1)});
